/// <summary>
/// VendEditInvoice form editReasonCode edit method extension
/// </summary>
[ExtensionOf(formControlStr(VendEditInvoice, editReasonCode))]
final class METVendEditInvoiceEditReasonCodeCtrl_Extension
{
}

Method.Source:
    /// <summary>
    /// validate the reason code to be enabled for invoice matching
    /// </summary>
    /// <returns>validation true/false</returns>
    public boolean validate()
    {
        boolean ret = next validate();

        if(ret && this.text())
        {
            if(!ReasonTable::find(this.text()).METInvoiceMatch)
            {
                ret = checkFailed("@MET:ReasonInvMatchingError");
            }
        }

        return ret;
    }
